export type HarnessListTriggersError = Error2;

export interface HarnessListTriggersParams {
  pageSize?: number;
  pageToken?: string;
  kind?: TriggerKind;
  status?: TriggerStatus;
}

function _harnessListTriggers(
  config: ClientConfig,
  { pageSize, pageToken, kind, status }: HarnessListTriggersParams = {},
  requestOptions?: RequestOptions,
): SdkPromise<SdkResource<ListTriggersResponse>> {
  return sdkPromise(
    async () => {
      if (pageSize != null) {
        validateRange("page_size", pageSize, { min: 1 });
      }

      return sdkRequest<ListTriggersResponse>({
        method: "GET",
        path: `/v2/agents/triggers`,
        operationId: "harnessListTriggers",
        errors: {
          "400": "Error2",
          "401": "Error2",
          "429": "Error2",
          "500": "Error2",
          default: "Error2",
        },
        responseDecoder: "json",
        ...requestOptions,
        query: {
          page_size: queryValue("page_size", pageSize, "form", true),
          page_token: queryValue("page_token", pageToken, "form", true),
          kind: queryValue("kind", kind, "form", true),
          status: queryValue("status", status, "form", true),
        },
        config,
      });
    },
    (_resp) =>
      sdkResource(
        sdkDecode(
          _resp,
          () => fromWire(_resp.data, "ListTriggersResponse") as ListTriggersResponse,
        ),
        _resp.data,
      ),
  );
}

/**
 * Keyset-paginated on an opaque cursor. Excludes soft-deleted triggers. Scoped to the authenticated team.
 *
 * @param pageSize - Page size. Defaults to 50 when omitted or non-positive;
 *   server-clamped.
 * @param pageToken - Opaque keyset cursor returned by the previous page. Empty
 *   starts from the beginning.
 * @param kind - Optional filter by trigger kind.
 * @param status - Optional filter by trigger status.
 */
export async function* harnessListTriggers(
  config: ClientConfig,
  params: HarnessListTriggersParams = {},
  requestOptions?: RequestOptions,
): AsyncGenerator<Trigger> {
  let _cursor = params.pageToken;
  while (true) {
    const _page = await _harnessListTriggers(
      config,
      { ...params, pageToken: _cursor },
      requestOptions,
    );
    const _items = _page.triggers ?? [];
    if (_items.length === 0) break;
    for (const item of _items) yield item;
    const _next = _page.nextPageToken;
    if (_next == null || _next === _cursor) break;
    _cursor = _next;
  }
}

export async function* harnessListTriggersPages(
  config: ClientConfig,
  params: HarnessListTriggersParams = {},
  requestOptions?: RequestOptions,
): AsyncGenerator<SdkPage<ListTriggersResponse, Trigger>> {
  let _cursor = params.pageToken;
  while (true) {
    const _page = await _harnessListTriggers(
      config,
      { ...params, pageToken: _cursor },
      requestOptions,
    );
    const _items = _page.triggers ?? [];
    if (_items.length === 0) break;
    const _next = _page.nextPageToken;
    const _hasMore = !(_next == null || _next === _cursor);
    yield new SdkPage(_page, _items, _hasMore);
    if (!_hasMore || _next == null) break;
    _cursor = _next;
  }
}
